function escapeHtml(value=''){const span=document.createElement('span');span.textContent=String(value);return span.innerHTML;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function normalizeContactSearch(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('de-DE').trim();}
function collectContactSearchValues(value,depth=0){if(value===null||value===undefined||depth>3)return[];if(['string','number','boolean'].includes(typeof value))return[String(value)];if(Array.isArray(value))return value.flatMap(item=>collectContactSearchValues(item,depth+1));if(typeof value==='object')return Object.values(value).flatMap(item=>collectContactSearchValues(item,depth+1));return[];}
function globalContactRecords(){
  const participantsById=new Map(participants.map(person=>[person.id,person]));
  const linkedLeadsByParticipant=new Map(leads.filter(lead=>lead.converted_user_profile_id).map(lead=>[lead.converted_user_profile_id,lead]));
  const customerRecords=participants.map(person=>{const linkedLead=linkedLeadsByParticipant.get(person.id)||leads.find(lead=>normalizeContactSearch(lead.email)===normalizeContactSearch(person.email));const phone=linkedLead?.phone||person.phone||'';return{key:`customer:${person.id}`,entityType:'participant',id:person.id,name:person.name,email:person.email,phone,customerNumber:person.customerNumber||'',status:person.week?`Woche ${person.week}`:'Onboarding',typeLabel:'Kunde',searchText:normalizeContactSearch(collectContactSearchValues([person.searchSource||person,linkedLead]).join(' '))};});
  const leadRecords=leads.filter(lead=>!lead.converted_user_profile_id||!participantsById.has(lead.converted_user_profile_id)).map(lead=>{const isCustomer=Boolean(lead.converted_user_profile_id);return{key:`${isCustomer?'customer':'lead'}:${lead.id}`,entityType:isCustomer?'participant':'lead',id:isCustomer?lead.converted_user_profile_id:lead.id,name:lead.name||`${lead.first_name||''} ${lead.last_name||''}`.trim()||'Kontakt ohne Namen',email:lead.email||'',phone:lead.phone||'',customerNumber:lead.customer_number||'',status:leadStatusLabels[lead.status]||lead.status||'Neu',typeLabel:isCustomer?'Kunde':'Interessent',searchText:normalizeContactSearch(collectContactSearchValues(lead).join(' '))};});
  return[...customerRecords,...leadRecords];
}
function globalContactMatches(query){const normalized=normalizeContactSearch(query);if(normalized.length<3)return[];return globalContactRecords().filter(record=>record.searchText.includes(normalized)||normalizeContactSearch(`${record.name} ${record.email} ${record.phone} ${record.customerNumber} ${record.status}`).includes(normalized)).map(record=>{const name=normalizeContactSearch(record.name),email=normalizeContactSearch(record.email),number=normalizeContactSearch(record.customerNumber);const score=name.startsWith(normalized)?0:name.includes(normalized)?1:email.startsWith(normalized)?2:number.startsWith(normalized)?2:3;return{...record,score};}).sort((a,b)=>a.score-b.score||a.name.localeCompare(b.name,'de')).slice(0,8);}
let globalContactSearchSelection=-1;
function closeGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;results.hidden=true;results.innerHTML='';input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');globalContactSearchSelection=-1;}
function renderGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;const query=input.value.trim();if(normalizeContactSearch(query).length<3)return closeGlobalContactSearch();const matches=globalContactMatches(query);globalContactSearchSelection=Math.min(globalContactSearchSelection,matches.length-1);results.innerHTML=matches.length?matches.map((record,index)=>`<button type="button" role="option" id="global-contact-result-${index}" class="global-contact-result ${index===globalContactSearchSelection?'active':''}" aria-selected="${index===globalContactSearchSelection}" data-global-contact="${escapeHtml(record.key)}"><span class="global-contact-avatar">${escapeHtml(record.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'?')}</span><span class="global-contact-copy"><strong>${escapeHtml(record.name)}</strong><small>${escapeHtml([record.email,record.phone].filter(Boolean).join(' · ')||'Keine Kontaktdaten hinterlegt')}</small><i>${escapeHtml([record.customerNumber,record.status].filter(Boolean).join(' · '))}</i></span><em class="global-contact-type ${record.entityType}">${escapeHtml(record.typeLabel)}</em><b aria-hidden="true">→</b></button>`).join(''):`<div class="global-contact-empty"><strong>Keine passende Akte gefunden</strong><span>Prüfe Name, E-Mail, Telefon, Kundennummer oder ein anderes Merkmal.</span></div>`;results.hidden=false;input.setAttribute('aria-expanded','true');if(globalContactSearchSelection>=0)input.setAttribute('aria-activedescendant',`global-contact-result-${globalContactSearchSelection}`);else input.removeAttribute('aria-activedescendant');results.querySelectorAll('[data-global-contact]').forEach(button=>button.addEventListener('click',()=>openGlobalContactResult(globalContactRecords().find(record=>record.key===button.dataset.globalContact))));}
async function openGlobalContactResult(record){if(!record)return;const input=document.querySelector('#globalCrmSearchInput');if(input)input.value='';closeGlobalContactSearch();if(record.entityType==='participant'){showView('participants');await openProgramControl(record.id);}else{showView('leads');await openLeadDashboard(record.id);}}
const globalCrmSearch=document.querySelector('#globalCrmSearch'),globalCrmSearchInput=document.querySelector('#globalCrmSearchInput');
globalCrmSearchInput?.addEventListener('input',()=>{globalContactSearchSelection=-1;renderGlobalContactSearch();});
globalCrmSearchInput?.addEventListener('focus',renderGlobalContactSearch);
globalCrmSearchInput?.addEventListener('keydown',event=>{const matches=globalContactMatches(globalCrmSearchInput.value);if(event.key==='Escape'){closeGlobalContactSearch();globalCrmSearchInput.blur();return;}if(!matches.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const direction=event.key==='ArrowDown'?1:-1;globalContactSearchSelection=globalContactSearchSelection<0?(direction>0?0:matches.length-1):(globalContactSearchSelection+direction+matches.length)%matches.length;renderGlobalContactSearch();}else if(event.key==='Enter'){event.preventDefault();openGlobalContactResult(matches[Math.max(0,globalContactSearchSelection)]);}});
document.addEventListener('click',event=>{if(globalCrmSearch&&!globalCrmSearch.contains(event.target))closeGlobalContactSearch();});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();globalCrmSearchInput?.focus();globalCrmSearchInput?.select();}});
function leadNavigationCounts(){const available=leads.filter(lead=>!lead.converted_user_profile_id&&lead.status!=='customer');return{all:available.length,active:available.filter(lead=>!['lost','later'].includes(lead.status)).length,lost:available.filter(lead=>lead.status==='lost').length,later:available.filter(lead=>lead.status==='later').length};}
function contextItemMarkup(item,index){const[title,description,target,settings,mailbox,communicationSection]=item;return`<button class="${index===0?'active':''}" data-context-target="${escapeHtml(target)}" ${settings?`data-context-settings="${escapeHtml(settings)}"`:''} ${mailbox?`data-context-mailbox="${escapeHtml(mailbox)}"`:''} ${communicationSection?`data-context-communication="${escapeHtml(communicationSection)}"`:''}><span>${String(index+1).padStart(2,'0')}</span><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div></button>`;}
function renderLeadListContextNavigation(nav,config){const counts=leadNavigationCounts();nav.innerHTML=config.groups.map((group,groupIndex)=>`<section class="lead-context-group"><button type="button" class="lead-context-group-toggle" data-lead-context-group="${groupIndex}" aria-expanded="true"><span>${escapeHtml(group.label)}</span><i>⌄</i></button><div class="lead-context-group-items">${group.items.map(([title,description,filter])=>`<button type="button" class="lead-context-filter ${leadListFilter===filter?'active':''}" data-lead-filter="${escapeHtml(filter)}"><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div>${filter==='all'?'':`<span>${counts[filter]||0}</span>`}</button>`).join('')}</div></section>`).join('');nav.querySelectorAll('[data-lead-context-group]').forEach(button=>button.addEventListener('click',()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));button.closest('.lead-context-group').classList.toggle('collapsed',expanded);}));nav.querySelectorAll('[data-lead-filter]').forEach(button=>button.addEventListener('click',()=>setLeadListFilter(button.dataset.leadFilter)));}
function renderContextNavigation(name){const config=contextNavigation[name]||contextNavigation.command;document.querySelector('#contextIcon').textContent=config.icon;document.querySelector('#contextTitle').textContent=titles[name]||titles.command;const nav=document.querySelector('#contextNav');if(name==='leads'&&!activeLeadDashboard)return renderLeadListContextNavigation(nav,config);const items=name==='leads'?config.detailItems:config.items;nav.innerHTML=`<p>${escapeHtml(config.label)}</p><nav>${items.map(contextItemMarkup).join('')}</nav>`;nav.querySelectorAll('[data-context-target]').forEach(button=>button.addEventListener('click',()=>{nav.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));if(button.dataset.contextSettings)showSettingsPanel(button.dataset.contextSettings);if(button.dataset.contextCommunication&&typeof setCommunicationSection==='function')setCommunicationSection(button.dataset.contextCommunication,button.dataset.contextMailbox);else if(button.dataset.contextMailbox)setCommunicationFolder(button.dataset.contextMailbox);const target=document.querySelector(`.view.active ${button.dataset.contextTarget}`);target?.scrollIntoView({behavior:'smooth',block:'start'});}));}
function showView(name){const isDashboard=name==='command',contextNav=document.querySelector('.context-nav');document.body.classList.toggle('dashboard-view',isDashboard);contextNav.hidden=isDashboard;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.panel===name));document.querySelectorAll('.sidebar nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelector('#viewTitle').textContent=titles[name];if(!isDashboard)renderContextNavigation(name);if(isDashboard)loadCommandDashboard();if(name==='gates')loadGateSettings();if(name==='communications'){loadCommunications();if(typeof loadCommunicationCenter==='function')loadCommunicationCenter();}window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.view==='leads')resetLeadListView();showView(button.dataset.view);}));
document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.jump)));
function showSettingsPanel(name){document.querySelectorAll('[data-settings-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.settingsPanel===name));document.querySelectorAll('[data-settings-tab]').forEach(button=>button.classList.toggle('active',button.dataset.settingsTab===name));if(name==='questions')loadClarityQuestions();if(name==='integrations')loadSystemStatus();}
document.querySelectorAll('[data-settings-tab]').forEach(button=>button.addEventListener('click',()=>showSettingsPanel(button.dataset.settingsTab)));
document.querySelectorAll('[data-settings-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.settingsJump)));

let clarityQuestions=[];
let clarityQuestionsLoaded=false;
const clarityTypeLabels={dialog:'Dialogfrage',scale:'Skala',upload:'Upload-Hinweis',confirmation:'Bestätigung',external:'Technischer Schritt',structured:'Strukturierter Schritt'};
function renderClarityQuestions(){const list=document.querySelector('#clarityQuestionList');if(!list)return;const week=document.querySelector('#clarityQuestionWeek')?.value||'';const query=(document.querySelector('#clarityQuestionSearch')?.value||'').trim().toLowerCase();const filtered=clarityQuestions.filter(item=>(!week||String(item.week)===week)&&(!query||`${item.title} ${item.prompt_text}`.toLowerCase().includes(query)));document.querySelector('#clarityQuestionCount').textContent=`${filtered.length} von ${clarityQuestions.length} Fragen`;list.innerHTML=filtered.length?filtered.map(item=>`<form class="clarity-question-card" data-question-key="${escapeHtml(item.question_key)}"><div class="question-card-head"><div><span>Woche ${Number(item.week)} · Schritt ${Number(item.sort_order)}</span><h4>${escapeHtml(item.title)}</h4></div><i>${escapeHtml(clarityTypeLabels[item.prompt_type]||item.prompt_type)}</i></div><label>Frage oder Arbeitsanweisung<textarea name="promptText" rows="3" minlength="5" maxlength="2000" required>${escapeHtml(item.prompt_text)}</textarea></label><div class="question-card-actions"><small>${item.prompt_text===item.default_prompt_text?'Standardfrage':'Individuell angepasst'}${item.updated_at?` · ${new Date(item.updated_at).toLocaleString('de-DE')}`:''}</small><div><button class="secondary" type="button" data-reset-question>Standard wiederherstellen</button><button class="primary" type="submit">Frage speichern</button></div></div></form>`).join(''):'<div class="empty">Keine Fragen für diesen Filter gefunden.</div>';}
async function loadClarityQuestions(force=false){if(clarityQuestionsLoaded&&!force){renderClarityQuestions();return;}const list=document.querySelector('#clarityQuestionList');if(list)list.innerHTML='<div class="empty">Klarheitsfragen werden geladen …</div>';try{const response=await fetch('/api/clarity?action=settings');const data=await response.json();if(!response.ok)throw new Error(data.error);clarityQuestions=data.questions||[];clarityQuestionsLoaded=true;renderClarityQuestions();}catch(error){if(list)list.innerHTML=`<div class="empty">${escapeHtml(error.message||'Klarheitsfragen konnten nicht geladen werden.')}</div>`;}}
async function updateClarityQuestion(form,action='save'){const questionKey=form.dataset.questionKey;const button=form.querySelector(action==='reset'?'[data-reset-question]':'button[type="submit"]');const promptText=form.elements.promptText.value.trim();button.disabled=true;try{const response=await fetch('/api/clarity?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({questionKey,promptText,action})});const data=await response.json();if(!response.ok)throw new Error(data.error);const index=clarityQuestions.findIndex(item=>item.question_key===questionKey);if(index>=0)clarityQuestions[index]={...clarityQuestions[index],...data.question};renderClarityQuestions();toast(action==='reset'?'Standardfrage wurde wiederhergestellt.':'Klarheitsfrage wurde gespeichert.');}catch(error){toast(error.message||'Klarheitsfrage konnte nicht gespeichert werden.');button.disabled=false;}}
document.querySelector('#clarityQuestionWeek')?.addEventListener('change',renderClarityQuestions);
document.querySelector('#clarityQuestionSearch')?.addEventListener('input',renderClarityQuestions);
document.querySelector('#clarityQuestionList')?.addEventListener('submit',event=>{const form=event.target.closest('[data-question-key]');if(!form)return;event.preventDefault();updateClarityQuestion(form);});
document.querySelector('#clarityQuestionList')?.addEventListener('click',event=>{const button=event.target.closest('[data-reset-question]');if(!button)return;const form=button.closest('[data-question-key]');if(confirm('Diese Frage wirklich auf den ausgelieferten Standard zurücksetzen?'))updateClarityQuestion(form,'reset');});

function accessModeLabel(){return 'Automatisch nach Zeitplan';}
function participantMarkup(person, table=false){const info=`<div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}</strong><small>${escapeHtml(person.email)}</small></div></div>`;if(table)return `<div class="table-data participant-control-row" data-participant-id="${escapeHtml(person.id)}">${info}<span class="phase"><b>${person.week?`Woche ${person.week}`:'Onboarding'}</b>${escapeHtml(person.programStatus||person.status)}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}% · ${escapeHtml(accessModeLabel(person.accessMode))}</div></div><strong>${person.startDate?new Date(`${person.startDate}T00:00:00`).toLocaleDateString('de-DE'):'—'}</strong><span class="gate"><button class="program-open" data-program-id="${escapeHtml(person.id)}">Programm steuern →</button></span></div>`;return `<div class="participant-row">${info}<span class="phase"><b>Woche ${person.week}</b>${escapeHtml(accessModeLabel(person.accessMode))}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}%</div></div><span class="gate"><b>${escapeHtml(person.next)}</b>${escapeHtml(person.programStatus||'aktiv')}</span></div>`;}
function renderParticipants(){const query=document.querySelector('#participantSearch')?.value.toLowerCase()||'',week=document.querySelector('#weekFilter')?.value||'';const filtered=participants.filter(p=>(!query||`${p.name} ${p.email}`.toLowerCase().includes(query))&&(!week||String(p.week)===week));document.querySelector('#dashboardParticipants').innerHTML=participants.length?participants.slice(0,4).map(p=>participantMarkup(p)).join(''):'<div class="empty">Noch keine Teilnehmer. Ein Lead erscheint hier automatisch nach vollständig bestätigtem Vertragsabschluss.</div>';document.querySelector('#participantRows').innerHTML=filtered.length?filtered.map(p=>participantMarkup(p,true)).join(''):'<div class="empty">Keine Teilnehmer gefunden.</div>';document.querySelectorAll('[data-program-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openProgramControl(button.dataset.programId);}));document.querySelectorAll('.participant-control-row').forEach(row=>row.addEventListener('click',()=>openProgramControl(row.dataset.participantId)));}

function dashboardNumber(value,digits=0){return Number(value||0).toLocaleString('de-DE',{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function renderDashboardClarity(clarity={}){const phases=clarity.phases||[],positions=[6,50,94],labels={start:'Start',midpoint:'Halbzeit',end:'Ende'};const points=phases.map((item,index)=>item.average===null||item.average===undefined?null:{...item,x:positions[index],y:10+Number(item.average)*8}).filter(Boolean);document.querySelector('#dashboardClarityLine').setAttribute('points',points.map(item=>`${item.x},${100-item.y}`).join(' '));document.querySelector('#dashboardClarityPoints').innerHTML=points.map(item=>`<span style="left:${item.x}%;bottom:${item.y}%">${dashboardNumber(item.average,1)}<small>${escapeHtml(labels[item.phase]||item.phase)} · ${item.count}</small></span>`).join('');document.querySelector('#dashboardClarityEmpty').hidden=points.length>0;const hasGain=clarity.averageGain!==null&&clarity.averageGain!==undefined;document.querySelector('#dashboardClarityGain').textContent=hasGain?`${Number(clarity.averageGain)>=0?'+':''}${dashboardNumber(clarity.averageGain,1)}`:'—';document.querySelector('#dashboardClarityCopy').textContent=clarity.completedComparisons?`${clarity.completedComparisons} vollständige Start-/Endmessung${clarity.completedComparisons===1?'':'en'} · Skala 1–10`:'Noch keine vollständige Start-/Endmessung';}
function renderDashboardDistribution(values=[],onboarding=0){const counts=Array.from({length:8},(_,index)=>Number(values[index]||0)),maximum=Math.max(1,...counts);document.querySelector('#dashboardWeekCounts').innerHTML=counts.map(value=>`<i style="height:${Math.max(25,25+value/maximum*70)}px">${value}</i>`).join('');document.querySelector('#dashboardWeekLabels').innerHTML=counts.map((value,index)=>`<span class="${value===maximum&&value>0?'current':''}">${index+1}</span>`).join('');document.querySelector('#dashboardOnboardingCount').textContent=`${Number(onboarding||0)} ${Number(onboarding)===1?'Kunde':'Kunden'} im Onboarding`;document.querySelectorAll('.metrics article.dark .bars i').forEach((bar,index)=>{bar.style.height=`${Math.max(12,counts[index]/maximum*100)}%`;});}
function dashboardEscalationCopy(summary={}){const counts=summary.escalationCounts||{},parts=[];if(counts.week_7_decision)parts.push(`${counts.week_7_decision} Entscheidung${counts.week_7_decision===1?'':'en'}`);if(counts.blocked_gate)parts.push(`${counts.blocked_gate} blockierte Gate${counts.blocked_gate===1?'':'s'}`);if(counts.q_and_a)parts.push(`${counts.q_and_a} Rückfrage${counts.q_and_a===1?'':'n'}`);if(counts.technical)parts.push(`${counts.technical} technisch`);return parts.length?parts.join(' · '):'Keine offenen Eskalationen';}
function openDashboardAction(item){if(!item?.entityId)return;if(item.entityType==='participant'){showView('participants');openProgramControl(item.entityId);}else if(item.entityType==='lead'){showView('leads');openLeadDashboard(item.entityId);}}
function renderDashboardAttention(attention={}){const list=document.querySelector('#dashboardAttentionList'),items=attention.items||[];document.querySelector('#dashboardAttentionCount').textContent=String(attention.total||0);list.innerHTML=items.length?items.map(item=>`<article data-dashboard-action="${escapeHtml(item.id)}"><i class="${escapeHtml(item.tone||'orange')}">${escapeHtml(item.icon||'!')}</i><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.subtitle)}</p></div><button type="button">${escapeHtml(item.actionLabel||'Öffnen')}</button></article>`).join(''):'<div class="empty">Aktuell gibt es keine offenen Vorgänge. Alles im grünen Bereich.</div>';list.querySelectorAll('[data-dashboard-action]').forEach(element=>element.addEventListener('click',()=>openDashboardAction(items.find(item=>item.id===element.dataset.dashboardAction))));}
function renderCommandDashboard(data){const generated=new Date(data.generatedAt||Date.now()),hour=generated.getHours(),firstName=(data.adminName||'Markus').trim().split(/\s+/)[0];document.querySelector('#dashboardDate').textContent=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(generated);document.querySelector('#dashboardGreeting').textContent=`${hour<11?'Guten Morgen':hour<18?'Guten Tag':'Guten Abend'}, ${firstName}.`;const summary=data.summary||{};document.querySelector('#dashboardLiveSummary').textContent=`${summary.activeLeads||0} Interessenten · ${summary.unreadMessages||0} ungelesene Nachrichten`;document.querySelector('#activeCustomerCount').textContent=String(summary.activeCustomers||0);document.querySelector('#dashboardNewCustomers').textContent=`+${summary.newCustomers||0} diesen Monat`;document.querySelector('#dashboardOpenGates').textContent=String(summary.openGates||0);document.querySelector('#dashboardOpenGateCopy').textContent=summary.openGates?`${summary.overdueGates||0} davon ohne Aktivität seit über 48 Stunden`:'Keine offenen Pflichtschritte';document.querySelector('#dashboardCoachNeeded').textContent=String(summary.coachNeeded||0);document.querySelector('#dashboardCoachCopy').textContent=dashboardEscalationCopy(summary);renderDashboardClarity(data.clarity);renderDashboardDistribution(data.weekDistribution,summary.onboarding);renderDashboardAttention(data.attention);}
async function loadCommandDashboard(){try{const response=await fetch('/api/leads?action=command-dashboard'),data=await response.json();if(!response.ok)throw new Error(data.error);renderCommandDashboard(data);}catch(error){document.querySelector('#dashboardLiveSummary').textContent='Live-Daten konnten nicht geladen werden';document.querySelector('#dashboardAttentionList').innerHTML=`<div class="empty system-error">${escapeHtml(error.message||'Dashboard konnte nicht geladen werden.')}</div>`;}}
function participantLoginStatus(person){if(person.mustChangePassword)return['Einmalpasswort aktiv','change'];if(person.passwordChangedAt)return['Persönliches Passwort','active'];return['Einrichtung offen','pending'];}
function renderParticipantLogins(){const rows=document.querySelector('#participantLoginRows');if(!rows)return;document.querySelector('#participantLoginCount').textContent=`${participants.length} ${participants.length===1?'Zugang':'Zugänge'}`;rows.innerHTML=participants.length?participants.map(person=>{const [label,tone]=participantLoginStatus(person);return `<div class="participant-login-row"><div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}</strong><small>${escapeHtml(person.email)}</small></div></div><strong>${escapeHtml(person.customerNumber||'Wird vergeben')}</strong><code>${escapeHtml(person.loginName||'Wird automatisch erzeugt')}</code><span class="login-state ${tone}">${escapeHtml(label)}</span><button type="button" class="user-manage" data-manage-participant-login="${escapeHtml(person.id)}">Verwalten →</button></div>`;}).join(''):'<div class="empty">Noch keine Teilnehmer-Zugänge vorhanden.</div>';rows.querySelectorAll('[data-manage-participant-login]').forEach(button=>button.addEventListener('click',()=>openParticipantLogin(button.dataset.manageParticipantLogin)));}
document.querySelector('#participantSearch').addEventListener('input',renderParticipants);document.querySelector('#weekFilter').addEventListener('change',renderParticipants);
let gateSettingsLoaded=false;
function renderGateGrid(){const grid=document.querySelector('#gateGrid');grid.innerHTML=gateData.map((gate,index)=>`<article class="gate-card ${index<3?'complete':index===3?'current':''}" data-gate-week="${gate.week}"><div class="gate-top"><span>${Number(gate.week)===0?'Start':`Woche ${Number(gate.week)}`}</span><div class="gate-card-tools"><i>${index<3?'Abgeschlossen':index===3?'Aktiv':'Gesperrt'}</i><button type="button" class="gate-menu" data-edit-gate="${gate.week}" aria-label="${escapeHtml(gate.title)} bearbeiten" title="Gate bearbeiten">•••</button></div></div><h2>${escapeHtml(gate.title)}</h2><p>${escapeHtml(gate.description)}</p><ul>${gate.items.map(item=>`<li><button type="button" data-edit-gate="${gate.week}" data-gate-key="${escapeHtml(item.gateKey)}"><span>${escapeHtml(item.label)}</span><small>Bearbeiten</small></button></li>`).join('')}</ul></article>`).join('');}
async function loadGateSettings(force=false){if(gateSettingsLoaded&&!force)return renderGateGrid();try{const response=await fetch('/api/gates?action=settings'),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();}catch(error){toast(error.message||'Wochen-Gates konnten nicht geladen werden.');renderGateGrid();}}
const gateSettingsDialog=document.querySelector('#gateSettingsDialog'),gateSettingsForm=document.querySelector('#gateSettingsForm');
function openGateSettings(week,fieldKey=''){const gate=gateData.find(item=>Number(item.week)===Number(week));if(!gate)return;gateSettingsForm.elements.week.value=String(gate.week);gateSettingsForm.elements.title.value=gate.title;gateSettingsForm.elements.description.value=gate.description;document.querySelector('#gateDialogWeek').textContent=Number(gate.week)===0?'Start · Onboarding':`Woche ${Number(gate.week)}`;document.querySelector('#gateFieldEditors').innerHTML=gate.items.map((item,index)=>`<div class="gate-field-editor"><span>${String(index+1).padStart(2,'0')}</span><label>Pflichtfeld ${index+1}<input name="gateLabel" data-gate-field-key="${escapeHtml(item.gateKey)}" value="${escapeHtml(item.label)}" minlength="2" maxlength="240" required><small>Die technische Gate-ID bleibt geschützt.</small></label></div>`).join('');gateSettingsDialog.showModal();const target=fieldKey?gateSettingsForm.querySelector(`[data-gate-field-key="${fieldKey}"]`):gateSettingsForm.elements.title;requestAnimationFrame(()=>target?.focus());}
async function saveGateSettings(action='save'){const button=gateSettingsForm.querySelector(action==='reset'?'[data-reset-gate]':'button[type="submit"]');button.disabled=true;try{const items=[...gateSettingsForm.querySelectorAll('[data-gate-field-key]')].map(input=>({gateKey:input.dataset.gateFieldKey,label:input.value.trim()}));const response=await fetch('/api/gates?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({week:Number(gateSettingsForm.elements.week.value),title:gateSettingsForm.elements.title.value.trim(),description:gateSettingsForm.elements.description.value.trim(),items,action})}),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();gateSettingsDialog.close();toast(action==='reset'?'Gate-Standard wurde wiederhergestellt.':'Wochen-Gate wurde gespeichert.');}catch(error){toast(error.message||'Wochen-Gate konnte nicht gespeichert werden.');}finally{button.disabled=false;}}
renderGateGrid();
document.querySelector('#gateGrid').addEventListener('click',event=>{const button=event.target.closest('[data-edit-gate]');if(button)openGateSettings(button.dataset.editGate,button.dataset.gateKey||'');});
document.querySelectorAll('[data-close-gate-settings]').forEach(button=>button.addEventListener('click',()=>gateSettingsDialog.close()));
gateSettingsForm.addEventListener('submit',event=>{event.preventDefault();saveGateSettings();});
gateSettingsForm.querySelector('[data-reset-gate]').addEventListener('click',()=>{if(confirm('Dieses Wochen-Gate wirklich auf den ausgelieferten Standard zurücksetzen?'))saveGateSettings('reset');});

const selectedPermissions=form=>[...form.querySelectorAll('[name="permissions"]:checked')].map(input=>input.value);
const userDialog=document.querySelector('#userDialog');document.querySelector('#openUser').addEventListener('click',()=>userDialog.showModal());document.querySelectorAll('[data-close-user]').forEach(b=>b.addEventListener('click',()=>userDialog.close()));document.querySelector('#userForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form));values.permissions=selectedPermissions(form);const response=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok)return toast(data.error);userDialog.close();form.reset();toast(data.passwordResetSent?'Benutzer angelegt. Passwort-E-Mail wurde versendet.':'Benutzer mit Startpasswort wurde angelegt.');loadUsers();});
const userEditDialog=document.querySelector('#userEditDialog');const userEditForm=document.querySelector('#userEditForm');document.querySelectorAll('[data-close-user-edit]').forEach(button=>button.addEventListener('click',()=>userEditDialog.close()));
function openUserEdit(id){const user=users.find(item=>item.id===id);if(!user)return;const participant=Boolean(user.participant_progress?.length);userEditForm.elements.id.value=user.id;userEditForm.elements.role.value=user.role;userEditForm.elements.status.value=user.status;document.querySelector('#editUserName').textContent=user.name;document.querySelector('#editUserEmail').textContent=user.email;userEditForm.querySelectorAll('[name="permissions"]').forEach(input=>{input.checked=(user.permissions||[]).includes(input.value);if(input.value==='clara_program'){input.disabled=!participant;input.closest('label').title=participant?'Teilnehmerzugang aus einem bestätigten Vertrag':'Wird erst nach bestätigtem Lead-Vertragsabschluss freigeschaltet';}});userEditDialog.showModal();}
userEditForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const payload={id:form.elements.id.value,role:form.elements.role.value,status:form.elements.status.value,permissions:selectedPermissions(form)};const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)return toast(data.error);userEditDialog.close();toast('Benutzerrechte wurden gespeichert.');loadUsers();});
document.querySelector('#resetUserPassword').addEventListener('click',async()=>{const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:userEditForm.elements.id.value,action:'password_reset'})});const data=await response.json();toast(response.ok?'Passwort-Reset wurde per E-Mail versendet.':data.error);});

const programDialog=document.querySelector('#programDialog');
document.querySelectorAll('[data-close-program]').forEach(button=>button.addEventListener('click',()=>programDialog.close()));
function renderProgramControl(data){
  programSnapshot=data;
  document.querySelector('#programParticipantId').value=data.profile.id;
  document.querySelector('#programParticipantName').textContent=data.profile.name;
  document.querySelector('#programParticipantEmail').textContent=data.profile.email;
  document.querySelector('#programStartDate').value=data.access.programStartDate||new Date().toISOString().slice(0,10);
  document.querySelector('#programStatus').value=data.access.status;
  document.querySelector('#programCurrentWeek').value=String(data.progress.current_week||0);
  document.querySelector('#programCalculatedWeek').textContent=data.access.status==='paused'?'Kunde pausiert · kein Wochenzugriff':`Aktuell zugänglich: ${data.access.unlockedWeeks.length?data.access.unlockedWeeks.map(week=>`W${week}`).join(', '):'keine Woche'}`;
  document.querySelector('#programAccessBadge').textContent='Automatisch · 7 Tage';
  const grouped=Object.groupBy?Object.groupBy(data.gates,gate=>gate.week):data.gates.reduce((result,gate)=>{(result[gate.week]||=[]).push(gate);return result;},{});
  document.querySelector('#programGateList').innerHTML=Object.entries(grouped).map(([week,gates])=>`<div class="gate-correction-week"><strong>${Number(week)===0?'Onboarding':`Woche ${week}`}</strong>${gates.map(gate=>`<label><input type="checkbox" data-correction-gate="${gate.id}" data-original="${Boolean(gate.completed_at)}" ${gate.completed_at?'checked':''}> ${escapeHtml(gate.label)}</label>`).join('')}</div>`).join('');
  const confirmations=data.technicalConfirmations||[];
  const reached=confirmations.filter(item=>item.status!=='not_reached');
  document.querySelector('#technicalConfirmationList').innerHTML=reached.length?reached.map(item=>item.status==='confirmed'
    ?`<article class="technical-confirmation confirmed"><div><span>Woche ${item.week}</span><strong>✓ ${escapeHtml(item.title)}</strong><small>Bestätigt ${item.confirmation?.confirmedAt?new Date(item.confirmation.confirmedAt).toLocaleString('de-DE'):''}</small></div>${item.confirmation?.resultReference?`<p>Referenz: ${escapeHtml(item.confirmation.resultReference)}</p>`:''}</article>`
    :`<article class="technical-confirmation pending" data-technical-card><div><span>Woche ${item.week} · wartet auf Admin-Prüfung</span><strong>${escapeHtml(item.title)}</strong><small>Der Kunde kann diesen Schritt nicht selbst freischalten.</small></div><label>Ergebnis / Referenz<input data-technical-reference placeholder="z. B. Bericht-ID, Termin oder Ablageort"></label><label>Prüfvermerk<textarea data-technical-note rows="3" placeholder="Was wurde geprüft und bestätigt?"></textarea></label><button type="button" class="primary" data-confirm-technical data-week="${item.week}" data-step-id="${escapeHtml(item.stepId)}">Geprüft und sicher bestätigen</button></article>`).join('')
    :'<div class="technical-empty">Aktuell wartet kein externer Journey-Schritt auf eine Admin-Bestätigung.</div>';
}

document.querySelector('#technicalConfirmationList').addEventListener('click',async event=>{
  const button=event.target.closest('[data-confirm-technical]');
  if(!button)return;
  const card=button.closest('[data-technical-card]');
  const note=card.querySelector('[data-technical-note]').value.trim();
  const resultReference=card.querySelector('[data-technical-reference]').value.trim();
  if(note.length<5)return toast('Bitte einen nachvollziehbaren Prüfvermerk eingeben.');
  if(!confirm(`Technisches Ergebnis „${card.querySelector('strong').textContent}“ verbindlich bestätigen?`))return;
  button.disabled=true;
  try{
    const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:document.querySelector('#programParticipantId').value,technicalConfirmation:{week:Number(button.dataset.week),stepId:button.dataset.stepId,note,resultReference}})});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error);
    renderProgramControl(data);
    toast('Technisches Ergebnis wurde auditierbar bestätigt.');
    await loadParticipants();
  }catch(error){toast(error.message);button.disabled=false;}
});
async function openProgramControl(participantId){if(!participantId)return;programDialog.showModal();document.querySelector('#programParticipantName').textContent='Wird geladen …';try{const response=await fetch(`/api/program-control?participantId=${encodeURIComponent(participantId)}`);const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);}catch(error){programDialog.close();toast(error.message);}}
document.querySelector('#resetParticipantToOnboarding').addEventListener('click',async()=>{const id=document.querySelector('#programParticipantId').value;if(!id)return;if(!confirm('Möchtest du diesen Kunden wirklich auf den Onboarding-Start zurücksetzen?'))return;try{const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:id,resetToOnboarding:true})});const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);programDialog.close();toast('Kunde wurde auf Onboarding zurückgesetzt.');await loadParticipants();}catch(error){toast(error.message);}});
document.querySelector('#programForm').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#saveProgram');button.disabled=true;const gateUpdates=[...document.querySelectorAll('[data-correction-gate]')].filter(input=>String(input.checked)!==input.dataset.original).map(input=>({gateId:input.dataset.correctionGate,completed:input.checked}));const payload={participantId:document.querySelector('#programParticipantId').value,programStartDate:document.querySelector('#programStartDate').value,programStatus:document.querySelector('#programStatus').value,currentWeek:Number(document.querySelector('#programCurrentWeek').value),gateUpdates};try{const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);programDialog.close();toast('Programmsteuerung wurde gespeichert.');await loadParticipants();}catch(error){toast(error.message);}finally{button.disabled=false;}});

async function loadParticipants(){try{const response=await fetch('/api/participants');const data=await response.json();if(!response.ok)throw new Error(data.error);participants=data.participants.map(p=>{const progress=p.participant_progress?.[0]||{};const parts=p.name.split(' ');return{id:p.id,name:p.name,email:p.email,loginName:p.portal_username||'',customerNumber:p.customer_number||'',mustChangePassword:p.must_change_password===true,passwordIssuedAt:p.one_time_password_issued_at||null,inviteSentAt:p.access_invite_sent_at||null,passwordChangedAt:p.password_changed_at||null,week:progress.current_week||0,status:progress.process_status||'ONBOARDING',programStatus:progress.program_status||p.status,accessMode:progress.access_mode||'time_based',startDate:progress.program_start_date||null,lastActivity:progress.last_activity_at||null,progress:Math.round((progress.current_week||0)/8*100),clarity:'—',next:'Programmsteuerung',initials:`${parts[0]?.[0]||''}${parts.at(-1)?.[0]||''}`,searchSource:p};});document.querySelector('#activeCustomerCount').textContent=String(participants.filter(item=>item.programStatus==='active').length);}catch(error){toast(error.message);}renderParticipants();renderParticipantLogins();renderGlobalContactSearch();}

const participantLoginDialog=document.querySelector('#participantLoginDialog'),participantLoginForm=document.querySelector('#participantLoginForm');
function showOneTimePassword(password=''){const result=document.querySelector('#oneTimePasswordResult');result.hidden=!password;document.querySelector('#oneTimePasswordValue').textContent=password;}
function openParticipantLogin(id,oneTimePassword=''){const person=participants.find(item=>item.id===id);if(!person)return;participantLoginForm.elements.id.value=person.id;participantLoginForm.elements.customerNumber.value=person.customerNumber||'Wird automatisch vergeben';participantLoginForm.elements.loginName.value=person.loginName||'';document.querySelector('#participantLoginName').textContent=person.name;document.querySelector('#participantLoginEmail').textContent=person.email;const [label]=participantLoginStatus(person);document.querySelector('#participantPasswordState').textContent=`${label}${person.inviteSentAt?` · E-Mail zuletzt ${new Date(person.inviteSentAt).toLocaleString('de-DE')}`:''}`;showOneTimePassword(oneTimePassword);participantLoginDialog.showModal();}
document.querySelectorAll('[data-close-participant-login]').forEach(button=>button.addEventListener('click',()=>participantLoginDialog.close()));
participantLoginForm.addEventListener('submit',async event=>{event.preventDefault();const button=participantLoginForm.querySelector('[type="submit"]');button.disabled=true;try{const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:participantLoginForm.elements.id.value,action:'update-login',loginName:participantLoginForm.elements.loginName.value})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadParticipants();participantLoginDialog.close();toast('Teilnehmer-Login wurde gespeichert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#issueOneTimePassword').addEventListener('click',async()=>{if(!confirm('Ein neues Einmalpasswort macht das bisherige Passwort sofort ungültig. Fortfahren?'))return;const button=document.querySelector('#issueOneTimePassword');button.disabled=true;try{const id=participantLoginForm.elements.id.value;const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'issue-one-time-password'})}),data=await response.json();if(!response.ok)throw new Error(data.error);const person=participants.find(item=>item.id===id);if(person){person.mustChangePassword=true;person.passwordIssuedAt=data.issuedAt;}showOneTimePassword(data.oneTimePassword);document.querySelector('#participantPasswordState').textContent='Neues Einmalpasswort aktiv · Passwortwechsel beim nächsten Login erforderlich';renderParticipantLogins();toast('Einmalpasswort wurde erzeugt und wird nur jetzt angezeigt.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#sendParticipantLoginMail').addEventListener('click',async()=>{const button=document.querySelector('#sendParticipantLoginMail');button.disabled=true;try{const id=participantLoginForm.elements.id.value;const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'send-login-mail'})}),data=await response.json();if(!response.ok)throw new Error(data.error);const person=participants.find(item=>item.id===id);if(person)person.inviteSentAt=data.sentAt;document.querySelector('#participantPasswordState').textContent=`Einmal-Link versendet · ${new Date(data.sentAt).toLocaleString('de-DE')}`;toast(data.message);}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#copyOneTimePassword').addEventListener('click',async()=>{const value=document.querySelector('#oneTimePasswordValue').textContent;if(!value)return;try{await navigator.clipboard.writeText(value);toast('Einmalpasswort wurde kopiert.');}catch{toast('Kopieren war nicht möglich. Bitte markiere das Passwort manuell.');}});
let bookingSettingsSnapshot=null;
const bookingDays=[['1','Montag'],['2','Dienstag'],['3','Mittwoch'],['4','Donnerstag'],['5','Freitag'],['6','Samstag'],['0','Sonntag']];
const bookingSettingsDialog=document.querySelector('#bookingSettingsDialog'),bookingSettingsForm=document.querySelector('#bookingSettingsForm');
const browserDateKey=(date=new Date())=>{const shifted=new Date(date.getTime()-date.getTimezoneOffset()*60000);return shifted.toISOString().slice(0,10);};
function addDateDays(dateKey,days){const date=new Date(`${dateKey}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10);}
function renderBookingSettings(settings){bookingSettingsSnapshot=settings;const enabledDays=bookingDays.filter(([day])=>settings.weeklyAvailability?.[day]?.length).map(([,label])=>label.slice(0,2));document.querySelector('#bookingDaysSummary').textContent=enabledDays.length?enabledDays.join(', '):'Keine';document.querySelector('#bookingDurationSummary').textContent=`${settings.defaultDurationMinutes} Min.`;document.querySelector('#bookingNoticeSummary').textContent=`${settings.minNoticeHours} Std.`;document.querySelector('#bookingHorizonSummary').textContent=`${settings.bookingHorizonDays} Tage`;const status=document.querySelector('#bookingConfigStatus');status.textContent=enabledDays.length?'Konfiguriert':'Noch nicht eingerichtet';status.classList.toggle('active',Boolean(enabledDays.length));document.querySelector('#weeklyAvailabilityRows').innerHTML=bookingDays.map(([day,label])=>{const window=settings.weeklyAvailability?.[day]?.[0],enabled=Boolean(window);return `<div class="availability-day ${enabled?'enabled':''}" data-availability-day="${day}"><label class="day-toggle"><input type="checkbox" ${enabled?'checked':''}> <b>${label}</b></label><label>von<input type="time" data-availability-start value="${window?.start||'09:00'}" ${enabled?'':'disabled'}></label><label>bis<input type="time" data-availability-end value="${window?.end||'17:00'}" ${enabled?'':'disabled'}></label></div>`;}).join('');bookingSettingsForm.elements.defaultDurationMinutes.value=String(settings.defaultDurationMinutes);bookingSettingsForm.elements.slotIntervalMinutes.value=String(settings.slotIntervalMinutes);bookingSettingsForm.elements.minNoticeHours.value=String(settings.minNoticeHours);bookingSettingsForm.elements.bookingHorizonDays.value=String(settings.bookingHorizonDays);document.querySelectorAll('[data-availability-day] .day-toggle input').forEach(input=>input.addEventListener('change',()=>{const row=input.closest('[data-availability-day]');row.classList.toggle('enabled',input.checked);row.querySelectorAll('input[type="time"]').forEach(field=>field.disabled=!input.checked);}));}
async function loadBookingSettings(){const response=await fetch('/api/leads?action=booking-settings'),data=await response.json();if(!response.ok)throw new Error(data.error);renderBookingSettings(data.settings);return data.settings;}
document.querySelector('#bookingSettings').addEventListener('click',async()=>{bookingSettingsDialog.showModal();try{await loadBookingSettings();}catch(error){bookingSettingsDialog.close();toast(error.message);}});
document.querySelectorAll('[data-close-booking-settings]').forEach(button=>button.addEventListener('click',()=>bookingSettingsDialog.close()));
bookingSettingsForm.addEventListener('submit',async event=>{event.preventDefault();const weeklyAvailability={0:[],1:[],2:[],3:[],4:[],5:[],6:[]};document.querySelectorAll('[data-availability-day]').forEach(row=>{if(row.querySelector('.day-toggle input').checked)weeklyAvailability[row.dataset.availabilityDay]=[{start:row.querySelector('[data-availability-start]').value,end:row.querySelector('[data-availability-end]').value}];});const payload={weeklyAvailability,defaultDurationMinutes:Number(bookingSettingsForm.elements.defaultDurationMinutes.value),slotIntervalMinutes:Number(bookingSettingsForm.elements.slotIntervalMinutes.value),minNoticeHours:Number(bookingSettingsForm.elements.minNoticeHours.value),bookingHorizonDays:Number(bookingSettingsForm.elements.bookingHorizonDays.value)};const button=bookingSettingsForm.querySelector('[type="submit"]');button.disabled=true;try{const response=await fetch('/api/leads?action=booking-settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error);bookingSettingsSnapshot=data.settings;bookingSettingsDialog.close();toast('Verfügbarkeit wurde gespeichert.');if(leadDialog.open){leadForm.elements.appointmentDuration.value=String(data.settings.defaultDurationMinutes);await loadAvailableSlots();}}catch(error){toast(error.message);}finally{button.disabled=false;}});
const leadStatusLabels={new:'Neu',contacted:'Kontaktiert',scheduled:'Termin vereinbart',consultation:'Gespräch geführt',offer:'Angebot offen',later:'Später Interesse',customer:'Kunde',lost:'Kein Interesse'};
const leadListDefinitions={all:{title:'Eingang',eyebrow:'Interessenten · Gewinnung',description:'Alle tatsächlich erfassten Interessenten mit Herkunft und Basisdaten.'},active:{title:'Aktive Interessenten',eyebrow:'Interessenten · Eingang',description:'Alle laufenden Vertriebsfälle vom neuen Eingang bis zum offenen Angebot.'},lost:{title:'Kein Interesse',eyebrow:'Interessenten · Eingang',description:'Interessenten, die aktuell nicht weiterverfolgt werden.'},later:{title:'Später Interesse',eyebrow:'Interessenten · Eingang',description:'Kontakte, die zu einem späteren Zeitpunkt erneut angesprochen werden sollen.'}};
const leadDialog=document.querySelector('#leadDialog'),leadForm=document.querySelector('#leadForm');
document.querySelectorAll('[data-close-lead]').forEach(button=>button.addEventListener('click',()=>leadDialog.close()));
function splitLeadName(lead){if(lead.first_name||lead.last_name)return[lead.first_name||'',lead.last_name||''];const parts=(lead.name||'').trim().split(/\s+/);return[parts.shift()||'',parts.join(' ')];}
function showSelectedSlot(iso){const selected=document.querySelector('#selectedSlot');if(!iso){selected.textContent='Noch keinen freien Termin ausgewählt';selected.classList.remove('chosen');return;}const date=new Date(iso);selected.textContent=`Ausgewählt: ${date.toLocaleString('de-DE',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})} Uhr`;selected.classList.add('chosen');}
async function loadAvailableSlots(){const container=document.querySelector('#availableSlots'),from=document.querySelector('#slotRangeStart').value||browserDateKey(),duration=Number(leadForm.elements.appointmentDuration.value);document.querySelector('#slotRangeStart').value=from;container.innerHTML='<p>Google Calendar wird auf freie Zeiten geprüft …</p>';try{const response=await fetch(`/api/leads?action=available-slots&from=${encodeURIComponent(from)}&to=${encodeURIComponent(addDateDays(from,13))}&duration=${duration}`),data=await response.json();if(!response.ok)throw new Error(data.error);bookingSettingsSnapshot=data.settings;if(!data.slots.length){container.innerHTML='<p>In diesem Zeitraum gibt es keine freigegebenen freien Termine. Passe den Zeitraum oder deine Verfügbarkeit an.</p>';return;}const groups=data.slots.reduce((result,slot)=>{(result[slot.date]||=[]).push(slot);return result;},{});container.innerHTML=Object.entries(groups).map(([date,slots])=>`<article><strong>${new Date(`${date}T12:00:00`).toLocaleDateString('de-DE',{weekday:'long',day:'2-digit',month:'2-digit'})}</strong><div>${slots.map(slot=>`<button type="button" data-slot-start="${escapeHtml(slot.start)}">${escapeHtml(slot.time)} Uhr</button>`).join('')}</div></article>`).join('');container.querySelectorAll('[data-slot-start]').forEach(button=>button.addEventListener('click',()=>{leadForm.elements.appointmentStart.value=button.dataset.slotStart;container.querySelectorAll('[data-slot-start]').forEach(item=>item.classList.toggle('selected',item===button));showSelectedSlot(button.dataset.slotStart);}));}catch(error){container.innerHTML=`<p>${escapeHtml(error.message)}</p>`;}}
function leadPayload(){const values=Object.fromEntries(new FormData(leadForm));return{id:values.id,firstName:values.firstName,lastName:values.lastName,email:values.email,phone:values.phone,status:values.status,challenge:values.challenge,internalNotes:values.internalNotes,qualificationAnswers:Object.fromEntries(Array.from({length:6},(_,index)=>[`q${index+1}`,values[`q${index+1}`]||'']))};}
function updateLeadCache(lead){const index=leads.findIndex(item=>item.id===lead.id);if(index>=0)leads[index]=lead;else leads.unshift(lead);}
function renderLeadDialog(lead){const[firstName,lastName]=splitLeadName(lead),answers=lead.qualification_answers||{};leadForm.elements.id.value=lead.id;leadForm.elements.firstName.value=firstName;leadForm.elements.lastName.value=lastName;leadForm.elements.email.value=lead.email||'';leadForm.elements.phone.value=lead.phone||'';leadForm.elements.status.value=lead.status||'new';leadForm.elements.challenge.value=lead.challenge||'';leadForm.elements.internalNotes.value=lead.internal_notes||'';for(let index=1;index<=6;index+=1)leadForm.elements[`q${index}`].value=answers[`q${index}`]||'';document.querySelector('#leadDialogTitle').textContent=lead.name;document.querySelector('#leadDialogSource').textContent=`${lead.utm_source||lead.source||'unbekannt'} · eingegangen ${new Date(lead.created_at).toLocaleDateString('de-DE')}`;leadForm.elements.appointmentStart.value=lead.appointment_start||'';if(lead.appointment_start&&lead.appointment_end)leadForm.elements.appointmentDuration.value=String(Math.round((new Date(lead.appointment_end)-new Date(lead.appointment_start))/60000));else if(bookingSettingsSnapshot)leadForm.elements.appointmentDuration.value=String(bookingSettingsSnapshot.defaultDurationMinutes);showSelectedSlot(lead.appointment_start);document.querySelector('#leadAppointmentState').textContent=lead.appointment_start?new Date(lead.appointment_start).toLocaleString('de-DE',{dateStyle:'medium',timeStyle:'short'}):'Noch kein Termin';const meet=document.querySelector('#openMeet'),calendar=document.querySelector('#openCalendarEvent'),cancel=document.querySelector('#cancelLeadAppointment');meet.classList.toggle('hidden',!lead.meet_url);calendar.classList.toggle('hidden',!lead.calendar_event_url);cancel.classList.toggle('hidden',!lead.calendar_event_id);if(lead.meet_url)meet.href=lead.meet_url;if(lead.calendar_event_url)calendar.href=lead.calendar_event_url;document.querySelector('#leadConversionState').textContent=lead.converted_user_profile_id?'Teilnehmerkonto automatisch angelegt':'Wartet auf vollständigen Vertragsabschluss';}
async function openLeadEditor(id){const lead=leads.find(item=>item.id===id)||activeLeadDashboard?.lead;if(!lead)return;document.querySelector('#slotRangeStart').value=browserDateKey();renderLeadDialog(lead);leadDialog.showModal();await loadAvailableSlots();}
const euro=value=>Number(value||0).toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const crmDate=value=>value?new Date(value).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}):'—';
const contractStatusLabels={draft:'Entwurf',sent:'Versendet',signed:'Unterschrieben',cancelled:'Storniert'};
const communicationLabels={inbound:'Eingang',outbound:'Ausgang',system:'System'};
function renderLeadTasks(){if(!activeLeadDashboard)return;const tasks=activeLeadDashboard.tasks||[],questions=activeLeadDashboard.questions||[];const items=leadTaskFilter==='questions'?questions:[...questions,...tasks];document.querySelector('#leadTaskList').innerHTML=items.length?items.map(item=>{const question=Boolean(item.question);if(question)return`<article class="question ${item.status==='answered'?'done':''}"><div><strong>Woche ${item.week} · Kundenfrage</strong><span>${item.status==='answered'?'Beantwortet':'Offen'}</span></div><p>${escapeHtml(item.question)}</p><small>${crmDate(item.created_at)}</small>${item.status==='open'?`<button class="lead-card-action" type="button" data-answer-question="${escapeHtml(item.id)}">Als beantwortet markieren</button>`:''}</article>`;return`<article class="${item.completed?'done':''}"><label><input type="checkbox" data-lead-task-id="${escapeHtml(item.id)}" ${item.completed?'checked':''}><span><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.details||'Interne Aufgabe')}</p><small>${item.due_at?`Fällig ${crmDate(item.due_at)}`:'Ohne Fälligkeit'}</small></span></label></article>`;}).join(''):'<div class="lead-empty">Noch keine Aufgaben oder Kundenfragen vorhanden.</div>';document.querySelectorAll('[data-lead-task-id]').forEach(input=>input.addEventListener('change',async()=>{try{await saveLeadDashboardRecord({recordType:'toggle_task',taskId:input.dataset.leadTaskId,completed:input.checked});}catch(error){input.checked=!input.checked;toast(error.message);}}));document.querySelectorAll('[data-answer-question]').forEach(button=>button.addEventListener('click',async()=>{try{await saveLeadDashboardRecord({recordType:'answer_question',questionId:button.dataset.answerQuestion});}catch(error){toast(error.message);}}));}
function renderSalesCallCard(lead){const answers=lead.qualification_answers||{},answered=Array.from({length:6},(_,index)=>answers[`q${index+1}`]).filter(value=>String(value||'').trim()).length;const completed=lead.status==='consultation'||['offer','customer'].includes(lead.status);document.querySelector('#leadSalesCallStatus').textContent=completed?'Gespräch geführt':lead.appointment_start?'Termin geplant':'Noch nicht geplant';document.querySelector('#leadSalesCallOverview').innerHTML=`<div><span>${lead.appointment_start?'✓':'○'}</span><p><b>Termin</b><small>${lead.appointment_start?crmDate(lead.appointment_start):'Noch nicht geplant'}</small></p></div><div><span>${answered===6?'✓':answered}</span><p><b>Gesprächsleitfaden</b><small>${answered} von 6 Antworten dokumentiert</small></p></div><div><span>${completed?'✓':'○'}</span><p><b>Abschlussentscheidung</b><small>${completed?'Gespräch abgeschlossen':'Noch offen'}</small></p></div>`;}
function renderLeadDashboard(data){activeLeadDashboard=data;const lead=data.lead,initials=lead.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();document.querySelector('#leadDashboardInitials').textContent=initials;document.querySelector('#leadDashboardName').textContent=lead.name;document.querySelector('#leadDashboardStatus').textContent=leadStatusLabels[lead.status]||lead.status;document.querySelector('#leadDashboardContact').textContent=`${lead.email} · ${lead.phone||'keine Telefonnummer'}`;document.querySelector('#leadDashboardConvert').textContent=lead.converted_user_profile_id?'Teilnehmerkonto verwalten →':'Vertragsabschluss erfassen →';const signed=(data.contracts||[]).some(item=>item.status==='signed'&&item.document_confirmed_at&&item.video_contract_confirmed_at);const stageByStatus={new:0,contacted:1,scheduled:2,consultation:3,offer:4,later:0,customer:6,lost:0};let current=stageByStatus[lead.status]??0;if(signed&&current<5)current=5;const stages=[['Anfrage','Eingegangen'],['Kontakt','Qualifizieren'],['Termin','Erstgespräch'],['Gespräch','Bedarf klar'],['Angebot','Entscheidung'],['Vertrag','Dokument + Video'],['Teilnehmer','8 Wochen']];document.querySelector('#leadSalesProgressCount').textContent=`Schritt ${current+1} von 7`;document.querySelector('#leadProgressTrack').innerHTML=stages.map(([title,copy],index)=>`<div class="lead-progress-step ${index<current?'done':index===current?'current':''}"><span>${index<current?'✓':index+1}</span><b>${title}</b><small>${copy}</small></div>`).join('');document.querySelector('#leadContactDetails').innerHTML=`<dl class="lead-detail-list"><div><dt>E-Mail</dt><dd>${escapeHtml(lead.email)}</dd></div><div><dt>Telefon</dt><dd>${escapeHtml(lead.phone||'Nicht hinterlegt')}</dd></div><div><dt>Quelle</dt><dd>${escapeHtml(lead.utm_source||lead.source||'Unbekannt')}</dd></div><div><dt>Anfrage</dt><dd>${escapeHtml(lead.challenge||'Nicht beschrieben')}</dd></div><div><dt>Eingang</dt><dd>${crmDate(lead.created_at)}</dd></div></dl>`;document.querySelector('#leadOpenBalance').textContent=euro(data.finance.openBalance);document.querySelector('#leadBalanceState').textContent=data.finance.openBalance>0?'Zahlung oder Restbetrag noch offen':'Keine offenen Forderungen';document.querySelector('#leadBalanceDetails').innerHTML=`<div><dt>Unterzeichnete Verträge</dt><dd>${euro(data.finance.contractTotal)}</dd></div><div><dt>Gebuchte Zahlungen</dt><dd>${euro(data.finance.paidTotal)}</dd></div>`;document.querySelector('#leadCommunicationList').innerHTML=data.communications.length?data.communications.map(item=>`<article><div><strong>${escapeHtml(item.subject)}</strong><span>${communicationLabels[item.direction]||item.direction}</span></div><p>${escapeHtml(item.preview||'Kein Vorschautext')}</p><small>${crmDate(item.occurred_at)}</small></article>`).join(''):'<div class="lead-empty">Noch kein E-Mail-Verkehr protokolliert. Termin- und Zugangsmails erscheinen hier automatisch.</div>';document.querySelector('#leadContractList').innerHTML=data.contracts.length?data.contracts.map(item=>`<article class="${item.status}"><div><strong>${escapeHtml(item.title)}</strong><span>${contractStatusLabels[item.status]||item.status}</span></div><p>${euro(item.amount)}${item.contract_number?` · ${escapeHtml(item.contract_number)}`:''}</p><div class="lead-contract-checks"><i class="${item.document_confirmed_at?'ok':''}">${item.document_confirmed_at?'✓':'○'} Vertragsdokument</i><i class="${item.video_contract_confirmed_at?'ok':''}">${item.video_contract_confirmed_at?'✓':'○'} Videovertrag</i></div><small>${item.signed_at?`Unterzeichnet ${crmDate(item.signed_at)}`:`Angelegt ${crmDate(item.created_at)}`}</small></article>`).join(''):'<div class="lead-empty">Noch kein Vertrag angelegt.</div>';document.querySelector('#leadNotesText').textContent=lead.internal_notes||'Noch keine internen Notizen vorhanden.';const bank=data.bankAccount;document.querySelector('#leadBankDetails').innerHTML=bank?`<div><dt>Kontoinhaber</dt><dd>${escapeHtml(bank.account_holder||'—')}</dd></div><div><dt>IBAN</dt><dd>${escapeHtml(bank.iban||'—')}</dd></div><div><dt>BIC</dt><dd>${escapeHtml(bank.bic||'—')}</dd></div><div><dt>Verwendungszweck</dt><dd>${escapeHtml(bank.payment_reference||'—')}</dd></div>`:'<div><dt>Status</dt><dd>Noch nicht hinterlegt</dd></div>';const next=[];if(!lead.appointment_start)next.push('Erstgespräch mit dem Interessenten planen');if(!data.contracts.length)next.push('Passenden Vertrag anlegen und versenden');else if(!signed&&!lead.converted_user_profile_id)next.push('Vertragsdokument und Videovertrag vollständig bestätigen');if(data.finance.openBalance>0)next.push(`${euro(data.finance.openBalance)} Zahlungseingang abgleichen`);if(!bank)next.push('Bankverbindung und Verwendungszweck hinterlegen');if(data.questions.some(item=>item.status==='open'))next.push(`${data.questions.filter(item=>item.status==='open').length} Kundenfrage(n) beantworten`);if(!next.length)next.push('Akte ist vollständig – nächsten persönlichen Kontakt planen');document.querySelector('#leadNextSteps').innerHTML=next.slice(0,4).map((item,index)=>`<div><span>${index+1}</span><p>${escapeHtml(item)}</p></div>`).join('');renderLeadTasks();renderSalesCallCard(lead);}
async function loadLeadDashboard(id=activeLeadDashboard?.lead?.id){if(!id)return;const response=await fetch(`/api/leads?action=dashboard&id=${encodeURIComponent(id)}`),data=await response.json();if(!response.ok)throw new Error(data.error);renderLeadDashboard(data);}
